def connected(edges,removed=-1):
 remaining=set(range(8))-{removed}
 seen={next(iter(remaining))};todo=list(seen)
 while todo:
  a=todo.pop()
  for x,y in edges:
   b=y if x==a else x if y==a else -1
   if b in remaining and b not in seen:seen.add(b);todo.append(b)
 return seen==remaining
